package solution

func Solve(nums []int) []int {
	seen := make(map[int]bool, len(nums)) // track values already added
	out := make([]int, 0, len(nums))      // pre-size to avoid reallocations
	for _, n := range nums {
		if !seen[n] {                     // first time we see n?
			seen[n] = true
			out = append(out, n)          // keep first-seen order
		}
	}
	return out
}

codeLab.testHarness:
package solution

import (
	"reflect"
	"testing"
)

func TestSolve(t *testing.T) {
	cases := []struct {
		in, want []int
	}{
		{[]int{1, 2, 2, 3, 1}, []int{1, 2, 3}},
		{[]int{}, []int{}},
		{[]int{5, 5, 5}, []int{5}},
	}
	for _, c := range cases {
		if got := Solve(c.in); !reflect.DeepEqual(got, c.want) {
			t.Errorf("Solve(%v)=%v want %v", c.in, got, c.want)
		}
	}
}

